import glob,re,os
# open ids
openids=set()
for f in glob.glob('items/*.yaml'):
    t=open(f).read()
    m=re.search(r'^status:[ ]*(\S+)',t,re.M)
    if m and m.group(1)=='open': openids.add(os.path.basename(f)[:-5])
pat=re.compile(r'(supersed\w*|absorb\w*|retract\w*|obsolet\w*|duplicat\w*|replaces|SUBSUMES)[^.\n]{0,120}?(I-\d{4})',re.I)
pat2=re.compile(r'(I-\d{4})[^.\n]{0,60}?(is now|was) (superseded|absorbed|retracted|archived)',re.I)
hits={}
for f in sorted(glob.glob('items/*.yaml'))+sorted(glob.glob('comments/*/*.md')):
    src=os.path.basename(f)[:-5] if f.startswith('items') else f.split('/')[1]
    if src not in openids: continue
    t=open(f).read()
    for m in pat.finditer(t):
        tgt=m.group(2)
        if tgt!=src: hits.setdefault((src,tgt),[]).append(m.group(0)[:150].replace(chr(10),' '))
    for m in pat2.finditer(t):
        tgt=m.group(1)
        if tgt!=src: hits.setdefault((src,tgt),[]).append(m.group(0)[:150].replace(chr(10),' '))
for (src,tgt),v in sorted(hits.items()):
    st='OPEN' if tgt in openids else 'not-open'
    print(f'{src} -> {tgt} [{st}] :: {v[0]}')
"
